using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();
        var app = await _appHost.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _chatClient;
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Greeting_ReturnsRelevantResponse()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0, "Expected at least one response message.");

        var evaluators = CreateQualityEvaluators();
        var result = await EvaluateAsync(messages, response, evaluators);

        AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 3.0);
        AssertMetricAboveThreshold(result, nameof(CoherenceEvaluator), 3.0);
    }

    [TestMethod]
    public async Task FactualQuestion_ReturnsGroundedAnswer()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(
            response.Messages.Any(m => m.Text?.Contains("Paris", StringComparison.OrdinalIgnoreCase) == true),
            "Expected the response to mention Paris.");

        var evaluators = CreateQualityEvaluators();
        var result = await EvaluateAsync(messages, response, evaluators);

        AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 4.0);
        AssertMetricAboveThreshold(result, nameof(CoherenceEvaluator), 4.0);
    }

    [TestMethod]
    public async Task MultiTurn_MaintainsCoherence()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan.")
        };

        var firstResponse = await _chatClient.GetResponseAsync(messages);
        Assert.IsNotNull(firstResponse);

        messages.AddRange(firstResponse.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "What are three must-see places there?"));

        var secondResponse = await _chatClient.GetResponseAsync(messages);
        Assert.IsNotNull(secondResponse);

        var evaluators = CreateQualityEvaluators();
        var result = await EvaluateAsync(messages, secondResponse, evaluators);

        AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 3.0);
        AssertMetricAboveThreshold(result, nameof(CoherenceEvaluator), 4.0);
    }

    private static List<IEvaluator> CreateQualityEvaluators()
    {
        return
        [
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
        ];
    }

    private static async Task<EvaluationResult> EvaluateAsync(
        IList<ChatMessage> messages,
        ChatResponse response,
        IList<IEvaluator> evaluators)
    {
        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            var turnResult = await evaluator.EvaluateAsync(
                messages,
                new ChatResponse(response.Messages),
                _evaluatorClient);

            foreach (var kvp in turnResult)
            {
                result.Add(kvp.Key, kvp.Value);
            }
        }

        return result;
    }

    private static void AssertMetricAboveThreshold(
        EvaluationResult result,
        string metricName,
        double threshold)
    {
        var metric = result.Values
            .OfType<NumericMetric>()
            .FirstOrDefault(m => m.Name.Contains(metricName, StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(metric, $"Metric '{metricName}' not found in evaluation results.");
        Assert.IsTrue(
            metric.Value >= threshold,
            $"Metric '{metricName}' scored {metric.Value}, which is below the threshold of {threshold}.");
    }
}

